        prev = Cb[i - 1]
        row[0] = 1
        row[i] = 1
        for j in range(1, i):
            row[j] = (prev[j - 1] + prev[j]) % P

    # dp[(parity of last layer, #even vertices used, last layer size)] = poly in (1+x)^K basis
    dp = {(0, 1, 1): [1]}

    for i in range(1, N):
        nd = {}
        rem = N - i
        for (p, e, c), w in dp.items():
            o = i - e
            lw = len(w)
