        return [comb(K,i)%P for i in range(K+1)]
    cache={}
    def coef(c,a):
        key=(c,a)
        if key in cache: return cache[key]
        res=[0]*(c*a+a*(a-1)//2+1)
        for k in range(a+1):
            w=comb(a,k)%P
            if k&1: w=(-w)%P
            bp=binpow(c*(a-k)+a*(a-1)//2)
            for i,v in enumerate(bp):
                res[i]=(res[i]+w*v)%P
        cache[key]=res
        return res
    dp=[dict() for _ in range(N+1)]
