    ans=[0]*(MAXE+1)
    for (p,e,c),w in dp[N].items():
        if e!=h: continue
        for M in range(N-1,min(len(w),MAXE+1)):
            ans[M]=(ans[M]+w[M])%P
    return ans[N-1:]

