def run(n,A,B,segs):
    full=(1<<B)-1; span=(1<<(B-A+1))-1; sh=A-1
    pos=1; mask=1; idx=0; steps=0
    while pos<n:
        if idx<len(segs) and segs[idx][0]==pos+1:
            r=segs[idx][1]; idx+=1
            shift=r-pos
            mask=0 if shift>=B else (mask<<shift)&full
            pos=r; continue
        e=segs[idx][0]-1 if idx<len(segs) else n
        seen={}; y=pos
        while y<e:
            steps+=1
            if mask in seen:
                prev=seen[mask]; period=y-prev; q=(e-y)//period
                if q>0:
                    y+=q*period; pos=y; seen.clear(); continue
            else: seen[mask]=y
            nb=1 if ((mask>>sh)&span) else 0
            mask=((mask<<1)|nb)&full; y+=1; pos=y
    return steps

